	'st_1' => 'Ein Raum ist vollendet, wenn die Menschen darin ihn nicht mehr wahrnehmen.',
	'st_2' => 'Wir gestalten für den hundertsten gewöhnlichen Tag, nicht für den ersten.',
	'st_3' => 'Kalkputz, Eiche und Leinen: drei Materialien, zu denen wir immer wieder zurückkehren.',
	'strip_1_l' => 'Vier Schichten, vier Tage, keine Farbe.',
